      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');

const ROOT = path.resolve(__dirname, '../..');
const DEP_MAP_PATH = path.join(ROOT, 'ChatMachines/GeminiSupervisor/dependency-map.json');
const CATALOG_PATH = path.join(ROOT, 'truth-reader/catalog.json');
const SELECTOR_PATH = path.join(ROOT, 'truth-reader/selector.json');
const EVIDENCE_PATH = path.join(ROOT, 'truth-reader/evidence.json');
const STATUS_PATH = path.join(ROOT, 'truth-reader/status.json');
const INTERNAL_STATE_PATH = path.join(ROOT, '.truth_reader_state.json');

function gitBlobSha(relPath) {
  try {
    return execSync(`git rev-parse HEAD:"${relPath}"`, { cwd: ROOT, stdio: ['ignore', 'pipe', 'ignore'] })
      .toString()
      .trim();
  } catch {
    return null;
  }
}

function validateSelectorSchema(selector, allowedKeys) {
  const keys = Object.keys(selector);
  for (const k of keys) {
    if (!allowedKeys.includes(k)) {
      throw new Error(`Rejected unauthorized key in selector: ${k}`);
    }
    if (typeof selector[k] !== 'boolean') {
      throw new Error(`Selector value for ${k} must be boolean, got ${typeof selector[k]}`);
    }
  }
}

function verifyProvenance(depEntry) {
  const currentBlob = gitBlobSha(depEntry.canonical_path);
  if (!currentBlob || currentBlob !== depEntry.source_blob_sha) {
    throw new Error(
      `Provenance mismatch for ${depEntry.canonical_path}: source blob SHA is ${currentBlob} but dependency map has ${depEntry.source_blob_sha}. Dependency sync required.`
    );
  }

  const fullReaderPath = path.join(ROOT, depEntry.reader_path);
  if (!fs.existsSync(fullReaderPath)) {
    throw new Error(`Stable reader missing at ${depEntry.reader_path}`);
  }
}

function injectSeeds(stableArray, challengeId, docKey) {
  const seededArray = [];
  const docSeeds = [];
  const total = stableArray.length;
  const targetSeedCount = Math.max(3, Math.min(10, Math.floor(total / 4) || 3));
  const interval = Math.max(1, Math.floor(total / targetSeedCount));
  let seedSeq = 0;

  for (let i = 0; i < total; i++) {
    seededArray.push(stableArray[i]);
    if ((i + 1) % interval === 0 && seedSeq < targetSeedCount) {
      const seedValue = crypto.randomBytes(24).toString('hex');
      docSeeds.push(seedValue);
      seededArray.push({
        type: 'truth_seed',
        challenge_id: challengeId,
        doc_key: docKey,
        seed_sequence: seedSeq++,
        seed: seedValue
      });
    }
  }

  if (seedSeq < targetSeedCount) {
    const seedValue = crypto.randomBytes(24).toString('hex');
    docSeeds.push(seedValue);
    seededArray.push({
      type: 'truth_seed',
      challenge_id: challengeId,
      doc_key: docKey,
      seed_sequence: seedSeq++,
      seed: seedValue
    });
  }

  return { seededArray, docSeeds };
}

function handleSelect() {
  const catalog = JSON.parse(fs.readFileSync(CATALOG_PATH, 'utf8')).documents;
  const depMap = JSON.parse(fs.readFileSync(DEP_MAP_PATH, 'utf8')).dependencies;
  const selector = JSON.parse(fs.readFileSync(SELECTOR_PATH, 'utf8'));

  validateSelectorSchema(selector, Object.keys(catalog));

  const selectedDocs = Object.keys(selector).filter((k) => selector[k] === true);
  if (selectedDocs.length === 0) {
    console.log('[truth-engine] No documents selected. Nothing to seed.');
    return;
  }

  console.log(`[truth-engine] Preparing active projections for: ${selectedDocs.join(', ')}`);

  for (const docKey of selectedDocs) {
    const catEntry = catalog[docKey];
    const depEntry = depMap[catEntry.dependency_key];
    if (!depEntry) {
      throw new Error(`Catalog key ${docKey} points to missing dependency entry ${catEntry.dependency_key}`);
    }
    verifyProvenance(depEntry);
  }

  const challengeId = crypto.randomBytes(16).toString('hex');
  const allExpectedSeeds = [];
  const generatedProjectionPaths = [];

  for (const docKey of selectedDocs) {
    const catEntry = catalog[docKey];
    const depEntry = depMap[catEntry.dependency_key];
    const fullReaderPath = path.join(ROOT, depEntry.reader_path);
    const stableArray = JSON.parse(fs.readFileSync(fullReaderPath, 'utf8'));

    const { seededArray, docSeeds } = injectSeeds(stableArray, challengeId, docKey);
    allExpectedSeeds.push(...docSeeds);

    const activeFullPath = path.join(ROOT, catEntry.active_projection_path);
    const activeDir = path.dirname(activeFullPath);
    if (!fs.existsSync(activeDir)) {
      fs.mkdirSync(activeDir, { recursive: true });
    }

    fs.writeFileSync(activeFullPath, JSON.stringify(seededArray, null, 2) + '\n');
    generatedProjectionPaths.push(catEntry.active_projection_path);
  }

  const internalState = {
    challenge_id: challengeId,
    selected_docs: selectedDocs,
    expected_seeds: allExpectedSeeds,
    projection_paths: generatedProjectionPaths,
    issued_at: new Date().toISOString()
  };
  fs.writeFileSync(INTERNAL_STATE_PATH, JSON.stringify(internalState, null, 2) + '\n');

  const status = {
    state: 'CHALLENGE_ISSUED',
    active_documents: selectedDocs,
    challenge_id: challengeId,
    issued_at: internalState.issued_at,
    completed_at: null,
    last_result: null
  };
  fs.writeFileSync(STATUS_PATH, JSON.stringify(status, null, 2) + '\n');
  console.log('[truth-engine] Active projections and internal challenge state generated successfully.');
}

function handleVerify() {
  if (!fs.existsSync(INTERNAL_STATE_PATH)) {
    console.error('[truth-engine] No active challenge state found. Skipping verification.');
    return;
  }

  const internalState = JSON.parse(fs.readFileSync(INTERNAL_STATE_PATH, 'utf8'));
  const evidence = JSON.parse(fs.readFileSync(EVIDENCE_PATH, 'utf8'));
  const submittedSeeds = Array.isArray(evidence.seeds) ? evidence.seeds : [];
  const expectedSeeds = internalState.expected_seeds || [];

  const matchesLength = submittedSeeds.length === expectedSeeds.length;
  let match = matchesLength;
  if (matchesLength) {
    for (let i = 0; i < expectedSeeds.length; i++) {
      if (submittedSeeds[i] !== expectedSeeds[i]) {
        match = false;
        break;
      }
    }
  }

  if (!match) {
    console.error('[truth-engine] Seed verification FAIL. Zero mutations performed.');
    process.exit(1);
  }

  console.log('[truth-engine] Seed verification PASS. Performing atomic reset commit.');

  for (const projRelPath of internalState.projection_paths || []) {
    const fullProj = path.join(ROOT, projRelPath);
    if (fs.existsSync(fullProj)) {
      fs.unlinkSync(fullProj);
    }
  }

  const selector = JSON.parse(fs.readFileSync(SELECTOR_PATH, 'utf8'));
  for (const k of Object.keys(selector)) {
    selector[k] = false;
  }
  fs.writeFileSync(SELECTOR_PATH, JSON.stringify(selector, null, 2) + '\n');
  fs.writeFileSync(EVIDENCE_PATH, JSON.stringify({ seeds: [] }, null, 2) + '\n');

  const status = {
    state: 'PASS',
    active_documents: [],
    challenge_id: internalState.challenge_id,
    issued_at: internalState.issued_at,
    completed_at: new Date().toISOString(),
    last_result: 'PASS'
  };
  fs.writeFileSync(STATUS_PATH, JSON.stringify(status, null, 2) + '\n');

  if (fs.existsSync(INTERNAL_STATE_PATH)) {
    fs.unlinkSync(INTERNAL_STATE_PATH);
  }
}

const mode = process.argv[2];
if (mode === '--select') {
  handleSelect();
} else if (mode === '--verify') {
  handleVerify();
} else {
  console.error('Usage: node truth-engine.js [--select | --verify]');
  process.exit(1);
}
